import base64, json, zlib

_PAYLOAD = """"""
MASTER = json.loads(zlib.decompress(base64.b64decode(_PAYLOAD)).decode("utf-8"))

def lookup(icube, fallback_name="", fallback_spec=""):
    code = str(icube or "").strip().upper()
    item = MASTER.get(code)
    if item:
        return {
            "name": str(item.get("name") or fallback_name or "제품명 미등록").replace("\\", ""),
            "type": str(item.get("type") or "-").replace("\\", ""),
            "size": str(item.get("size") or "-").replace("\\", ""),
            "category": str(item.get("category") or "-").replace("\\", ""),
            "mapped": True,
            "icube": code,
        }
    return {
        "name": fallback_name or "제품명 미등록",
        "type": "마스터 미등록",
        "size": fallback_spec or "-",
        "category": "확인 필요",
        "mapped": False,
        "icube": code,
    }
